INSERT INTO news_posts(id, slug, title, excerpt, body, cover_id, image_alt, status, published_at, updated_at)
VALUES(
  'e0000000-0000-4000-8000-000000000037'::uuid,
  'ky-nang-su-dung-micro-cai-ao-khong-day-quay-video',
  'Kỹ năng làm chủ micro cài áo không dây: Cách giấu mic, gài vị trí chuẩn và kiểm soát độ nhạy khi quay video',
  'Hướng dẫn chi tiết từ khoảng cách vàng gài micro trên cổ áo, kỹ thuật giấu dây thẩm mỹ cho khung hình chuyên nghiệp đến cách cân chỉnh mức Gain để âm thanh không vỡ hạt.',
  'Micro cài áo không dây (như dòng GAERU K9) là công cụ giải phóng sự tự do tối đa cho nhà sáng tạo nội dung khi quay video ngắn, vlog hoặc phỏng vấn đường phố. Tuy nhiên, nếu gài sai vị trí hoặc không kiểm soát tốt độ nhạy, âm thanh sẽ dễ bị nghẹt, rè hoặc lẫn tiếng sột soạt của vải áo.

1. "Khoảng cách vàng" 15 đến 20cm từ miệng đến micro
Vị trí lý tưởng nhất để gài micro cài áo là phần xương ức ngực, cách miệng khoảng một gang tay (15 - 20cm).
- Nếu gài quá sát cổ hoặc cằm: Luồng hơi thở mạnh khi phát âm các phụ âm bật như "p", "b", "t" sẽ đập trực tiếp vào màng thu gây ra tiếng nổ lụp bụp (plosives).
- Nếu gài quá thấp ngang bụng: Âm lượng giọng nói bị suy giảm rõ rệt, buộc bộ thu phải khuếch đại gain lên cao, vô tình kéo theo nhiều tạp âm nền xung quanh.
- Mẹo định hướng: Hãy hướng đầu thu của micro hơi chếch nhẹ về phía cằm, tránh để mặt màng thu cọ xát trực tiếp vào cổ áo sơ mi hay vạt áo khoác.

2. Kỹ thuật giấu dây và kẹp mic thẩm mỹ không lộ trước ống kính
Trong các video chuyên nghiệp, việc giấu micro khéo léo giúp người xem tập trung 100% vào nội dung câu chuyện thay vì bị phân tâm bởi một cục nhựa đen gắn lộ liễu trên áo.
- Luồn dây từ trong áo: Đưa củ phát hoặc dây cài luồn từ mép trong gấu áo đi lên phía ngực.
- Dùng kỹ thuật kẹp hình chữ V: Kẹp micro phía sau nẹp áo sơ mi hoặc phía trong cổ áo phông, chỉ để lộ phần đầu kẹp nhỏ tinh tế.
- Chèn đệm chống ma sát: Dán một mẩu băng dính y tế hoặc xốp bọt biển nhỏ phía sau lưng mic để triệt tiêu hoàn toàn tiếng cọ xát giữa thân mic và thớ vải khi bạn cử động cơ thể.

3. Kiểm soát mức Gain và âm lượng đầu vào trên điện thoại
Một lỗi phổ biến là để âm lượng đầu vào quá lớn dẫn đến hiện tượng méo tiếng (clipping) không thể cứu vãn ở khâu hậu kỳ.
- Quy tắc -6dB: Khi kiểm tra giọng nói to nhất (như cười hoặc nhấn mạnh câu từ), cột sóng âm trên ứng dụng thu âm chỉ nên chạm tới ngưỡng vàng (-12dB đến -6dB), tuyệt đối không để vọt sang vạch đỏ (0dB).
- Đeo tai nghe kiểm âm trước khi bấm quay: GAERU K9 hỗ trợ kết nối Type-C/Lightning trực tiếp. Hãy luôn thực hiện một đoạn thu thử 10 giây và nghe lại qua tai nghe để chắc chắn tín hiệu trong trẻo.

4. Bảo quản pin và giữ khoảng cách truyền sóng ổn định
Micro không dây truyền sóng 2.4GHz rất nhạy cảm với vật cản kim loại lớn hoặc cơ thể người chắn ngang đường truyền thẳng.
- Đặt đầu thu (Receiver) ở vị trí thông thoáng, hướng thẳng về phía người nói.
- Sau mỗi buổi quay, cất mic vào hộp sạc để tiếp điểm luôn sạch sẽ và sẵn sàng năng lượng cho buổi quay tiếp theo.

Tìm hiểu chi tiết các dòng micro cài áo GAERU K9 chính hãng tại https://gaeru.com/cua-hang và xem hướng dẫn kết nối tại https://gaeru.com/tin-tuc/gaeru-k9-chon-cong-ket-noi-va-bo-mic.',
  'a0000000-0000-4000-8000-000000000037'::uuid,
  'Kỹ năng làm chủ micro cài áo không dây: Cách giấu mic, gài vị trí chuẩn và kiểm soát độ nhạy khi quay video',
  'published',
  '2026-11-05T07:45:00Z'::timestamptz,
  now()
)
