INSERT INTO news_posts(id, slug, title, excerpt, body, cover_id, image_alt, status, published_at, updated_at)
VALUES(
  'e0000000-0000-4000-8000-000000000038'::uuid,
  'ky-nang-su-dung-gimbal-chong-rung-quay-video-muot-ma',
  'Kỹ năng sử dụng gimbal chống rung: Các bước cân bằng trọng tâm và chuyển động bước đi Ninja mượt mà',
  'Bí quyết cân gimbal chuẩn xác trước khi bật nguồn giúp motor bền bỉ, kỹ thuật bước đi Ninja Walk triệt tiêu rung lắc trục dọc và 5 góc máy điện ảnh cơ bản.',
  'Sở hữu một chiếc gimbal chống rung thông minh (như GAERU P01 hay gậy gimbal P185) là bước đệm quan trọng để nâng cấp thước phim từ nghiệp dư lên chuẩn điện ảnh. Tuy nhiên, gimbal là thiết bị cơ điện tử chính xác đòi hỏi người quay phải nắm vững kỹ thuật vận hành để khai thác trọn vẹn sức mạnh.

1. Nguyên tắc sống còn: Cân bằng trọng tâm vật lý trước khi bấm nguồn
Sai lầm lớn nhất của người mới là kẹp điện thoại vào gimbal rồi bật nguồn ngay lập tức. Khi đó, các motor điện từ phải gồng mình hoạt động quá tải để giữ thăng bằng, dẫn đến nóng máy, hao pin nhanh gấp 3 lần và giảm tuổi thọ thiết bị.
- Bước 1: Kẹp điện thoại vào chính giữa ngàm, tháo ốp lưng quá dày nếu có.
- Bước 2: Điều chỉnh cánh tay đòn sao cho khi CHƯA bật nguồn, điện thoại vẫn tự giữ thăng bằng nằm ngang mà không bị chúc đầu xuống dưới hoặc nghiêng hẳn sang một bên.
- Bước 3: Sau khi đã đạt trạng thái cân bằng cơ học tự nhiên, mới nhấn giữ nút nguồn khởi động. Lúc này motor chỉ cần một lực rất nhỏ để giữ khung hình ổn định tuyệt đối.

2. Kỹ thuật di chuyển "Ninja Walk" triệt tiêu chấn động trục dọc (Z-axis)
Gimbal 3 trục có thể xử lý hoàn hảo rung lắc theo trục xoay (Pan), nghiêng (Tilt) và lật (Roll), nhưng KHÔNG THỂ triệt tiêu rung động lên xuống theo bước chân (trục Z). Đó là lý do nhiều người dùng gimbal mà khung hình vẫn bị nhấp nhô theo từng bước đi.
- Tư thế bước đi Ninja: Hơi khuỵu hai đầu gối xuống khoảng 15 - 20 độ, hạ thấp trọng tâm cơ thể.
- Bước chạm từ gót sang mũi chân: Di chuyển nhẹ nhàng, đặt gót chân xuống trước rồi từ từ lăn sang mũi chân, giữ cho phần thân trên di chuyển trên một đường thẳng nằm ngang phẳng lặng.
- Hai tay giữ gimbal: Sử dụng cả hai tay hoặc giữ khuỷu tay cong nhẹ sát hông để làm một "hệ thống treo thứ cấp" hỗ trợ hấp thụ chấn động.

3. 5 cú máy điện ảnh cơ bản nhưng tạo ấn tượng thị giác mạnh
- Push-In (Tiến lại gần): Di chuyển từ từ về phía chủ thể đang nói để tăng cảm giác gần gũi và kịch tính.
- Pull-Out (Lùi dần ra xa): Mở rộng không gian hậu cảnh, tạo cảm giác chia tay hoặc hé lộ bối cảnh rộng lớn.
- Parallax / Orbit (Quay vòng quanh): Giữ chủ thể ở chính giữa khung hình và bước vòng tròn quanh họ để tạo hiệu ứng 3D thị giác bắt mắt.
- Low-Angle Tracking (Bám sát góc thấp): Hạ thấp gimbal sát mặt đất để quay bước chân hoặc góc nhìn độc lạ.
- Reveal Shot (Cú máy hé lộ): Đi từ phía sau một vật cản (bức tường, cánh cửa, tán cây) rồi từ từ quét máy sang để mở ra chủ thể chính.

4. Tận dụng tính năng Face Tracking thông minh của GAERU P01
Dòng gimbal GAERU P01 tích hợp mắt thần AI nhận diện khuôn mặt tự động độc lập, không cần phụ thuộc vào ứng dụng bên thứ ba.
- Khi quay một mình, hãy đặt gimbal lên tripod mini cách bạn 1.5 - 2.5m.
- Sử dụng cử chỉ bàn tay (Hand Gesture) giơ lòng bàn tay lên để kích hoạt bám theo, và giơ ký hiệu chữ V để tạm dừng. Tính năng này giải phóng hoàn toàn đôi tay cho nhà sáng tạo.

Khám phá bộ sưu tập gimbal và gậy quay chống rung GAERU tại https://gaeru.com/cua-hang và tra cứu cẩm nang sử dụng tại https://gaeru.com/tin-tuc/gaeru-p01-khung-doc-ngang-video.',
  'a0000000-0000-4000-8000-000000000038'::uuid,
  'Kỹ năng sử dụng gimbal chống rung: Các bước cân bằng trọng tâm và chuyển động bước đi Ninja mượt mà',
  'published',
  '2026-11-05T07:44:00Z'::timestamptz,
  now()
)
