INSERT INTO news_posts(id, slug, title, excerpt, body, cover_id, image_alt, status, published_at, updated_at)
VALUES(
  'e0000000-0000-4000-8000-000000000039'::uuid,
  'ky-nang-setup-anh-sang-quay-video-livestream-chuyen-nghiep',
  'Kỹ năng setup ánh sáng 3 điểm (Three-Point Lighting): Bí quyết để khuôn mặt sáng đẹp và nổi bật chủ thể khi quay live',
  'Làm chủ ánh sáng chính (Key Light), đèn phụ làm mềm bóng (Fill Light) và đèn ven tóc (Back Light) giúp tạo chiều sâu không gian và tôn vinh thần thái khi phát sóng trực tiếp.',
  'Trong nhiếp ảnh và quay video, "Ánh sáng là linh hồn của khung hình". Dù bạn sở hữu chiếc điện thoại đắt tiền nhất với camera 200MP, nếu quay trong điều kiện thiếu sáng hoặc ánh sáng chiếu sai góc, hình ảnh vẫn sẽ bị nhiễu hạt (noise), khuôn mặt u tối và làn da kém sắc. Nắm vững công thức ánh sáng 3 điểm kinh điển là chìa khóa để video của bạn luôn rạng rỡ.

1. Đèn chính (Key Light) - Nguồn sáng định hình thần thái
Key Light là nguồn sáng mạnh nhất và quan trọng nhất trong toàn bộ khung hình, đảm nhận nhiệm vụ chiếu sáng khuôn mặt người nói.
- Vị trí đặt: Đặt đèn chếch một góc 45 độ so với trục giữa của camera và nâng cao hơn tầm mắt của bạn khoảng 30 - 45cm, chúc góc đèn xuống 45 độ.
- Hiệu ứng đạt được: Tạo ra vệt sáng hình tam giác đặc trưng trên má đối diện (kiểu chiếu sáng Rembrandt cổ điển), giúp khuôn mặt thon gọn, có đường nét thanh thoát và sống động hơn rất nhiều so với đèn chiếu thẳng trực diện.
- Chọn loại đèn: Nên sử dụng đèn LED dạng Softbox hoặc Ring Light có tản sáng mềm để ánh sáng tỏa đều, không gây chói gắt vùng sống mũi và trán.

2. Đèn phụ (Fill Light) - Làm mềm và cân bằng bóng đổ
Nếu chỉ sử dụng đèn chính, một nửa khuôn mặt của bạn sẽ chìm vào bóng tối sâu, tạo cảm giác quá tương phản và nặng nề. Đó là lúc cần đến Fill Light.
- Vị trí đặt: Đặt đối xứng với Key Light qua trục camera (góc 45 độ bên phía còn lại).
- Cường độ: Thiết lập công suất chỉ bằng khoảng 30% - 50% so với đèn chính. Nhiệm vụ của Fill Light không phải là triệt tiêu bóng tối hoàn toàn, mà là nâng sáng vùng bóng mờ để người xem vẫn nhìn rõ chi tiết má và khóe mắt.

3. Đèn ven / Đèn tóc (Back Light / Hair Light) - Tạo chiều sâu 3D
Đây chính là bí mật tạo nên sự khác biệt giữa một video nghiệp dư "phẳng lì" và một khung hình điện ảnh có chiều sâu cuốn hút.
- Vị trí đặt: Treo hoặc đặt đèn phía sau lưng chủ thể, chếch một góc cao chiếu nhẹ vào vai gáy và đỉnh tóc.
- Hiệu quả thị giác: Ánh sáng ven viền quanh mái tóc và bờ vai giúp tách biệt hoàn toàn chủ thể ra khỏi bức tường hoặc phông nền phía sau, mang lại cảm giác không gian đa chiều, sang trọng và chuyên nghiệp.

4. Đồng bộ nhiệt độ màu (Color Temperature) và ánh sáng môi trường
- Đèn ấm (3200K) mang lại cảm giác hoài niệm, ấm áp; đèn trắng ban ngày (5600K) tạo vẻ hiện đại, năng động và tôn đúng màu sản phẩm.
- Khi livestream bán hàng thời trang hoặc mỹ phẩm, luôn ưu tiên đèn có chỉ số hoàn màu CRI > 95 và giữ nhiệt độ màu ở mức 5000K - 5600K để khách hàng nhìn thấy màu son, màu vải chân thực nhất.

Khám phá các thiết bị hỗ trợ quay chụp GAERU tại https://gaeru.com/cua-hang và xem thêm cẩm nang livestream bán hàng tại https://gaeru.com/tin-tuc/ky-thuat-livestream-tiktok-shop-am-thanh-nguon-dien.',
  'a0000000-0000-4000-8000-000000000039'::uuid,
  'Kỹ năng setup ánh sáng 3 điểm (Three-Point Lighting): Bí quyết để khuôn mặt sáng đẹp và nổi bật chủ thể khi quay live',
  'published',
  '2026-11-05T07:43:00Z'::timestamptz,
  now()
)
