INSERT INTO news_posts(id, slug, title, excerpt, body, cover_id, image_alt, status, published_at, updated_at)
VALUES(
  'e0000000-0000-4000-8000-000000000041'::uuid,
  'ky-nang-phoi-hop-thiet-bi-livestream-am-thanh-hinh-anh-on-dinh',
  'Kỹ năng đồng bộ thiết bị Livestream: Kết nối âm thanh, hình ảnh và nguồn điện liên tục không gián đoạn',
  'Quy trình kiểm tra checklist 5 bước trước giờ lên sóng: cấp nguồn trực tiếp qua cổng sạc receiver, đồng bộ độ trễ âm hình và thiết lập chân đỡ điện thoại góc nhìn mắt thẳng.',
  'Một phiên livestream bán hàng kéo dài từ 2 đến 4 tiếng đồng hồ là bài kiểm tra khắc nghiệt nhất đối với sự ổn định của hệ thống thiết bị. Bất kỳ sự cố nào như điện thoại hết pin sập nguồn, micro mất kết nối hay hình đi trước tiếng đi sau đều khiến khán giả rời bỏ phòng live ngay lập tức. Để vận hành trơn tru, bạn cần có tư duy phối hợp thiết bị có hệ thống.

1. Giải bài toán năng lượng: Tận dụng cổng sạc xuyên (Pass-Through Charging)
Khi cắm đầu thu micro vào cổng Type-C hoặc Lightning của điện thoại, cổng sạc duy nhất của máy đã bị chiếm dụng. Vậy làm sao để livestream liên tục 4 tiếng mà không cạn pin?
- Sử dụng đầu thu hỗ trợ sạc ngoài như GAERU K9: Trên cạnh thân Receiver của K9 được tích hợp sẵn cổng cắm sạc phụ Type-C.
- Kết nối thông minh: Bạn chỉ cần cắm dây sạc pin dự phòng hoặc củ sạc tường vào cổng phụ này, dòng điện sẽ tự động truyền xuyên qua Receiver để nạp thẳng vào điện thoại với công suất ổn định, vừa thu âm vừa sạc pin liên tục không sợ gián đoạn.

2. Kiểm soát độ trễ âm hình (Audio/Video Latency)
Trên các nền tảng như TikTok Shop hay Shopee Live, việc khẩu hình miệng lệch với âm thanh phát ra tạo cảm giác cực kỳ khó chịu.
- Nguyên nhân chính: Sử dụng tai nghe hoặc loa Bluetooth không dây có độ trễ cao (150ms - 300ms) để kiểm âm.
- Giải pháp: Luôn ưu tiên đường truyền tín hiệu có dây hoặc sóng vô tuyến 2.4GHz chuyên dụng (như GAERU K9) với độ trễ cực thấp chỉ dưới 15ms. Tắt hoàn toàn các kết nối Bluetooth phụ không cần thiết trên điện thoại để giải phóng băng thông truyền tải.

3. Thiết lập góc máy ngang tầm mắt (Eye-Level Camera)
- Không quay góc ngửa từ dưới lên: Khiến bạn lộ cằm ngấn và tạo cảm giác bề trên thiếu thiện cảm với người xem.
- Không quay góc chúi từ trên xuống: Khiến thân hình bị lùn và thao tác giới thiệu sản phẩm bị gò bó.
- Sử dụng gậy tripod GAERU P185 hoặc gimbal P01: Kéo dài chân tripod đặt vững trên bàn hoặc sàn nhà, nâng máy sao cho ống kính camera nằm ngang đúng bằng tầm mắt khi bạn ngồi hoặc đứng. Góc nhìn trực diện tạo cảm giác bạn đang nhìn thẳng vào mắt khách hàng để trò chuyện chân tình.

4. Bảng kiểm tra (Checklist) 5 phút trước giờ lên sóng
- Bước 1: Vệ sinh sạch sẽ ống kính camera trước và sau bằng khăn microfiber mềm.
- Bước 2: Bật chế độ "Không làm phiền" (Do Not Disturb) và khóa xoay màn hình trên điện thoại.
- Bước 3: Cắm receiver micro, kiểm tra đèn báo kết nối chuyển sang màu xanh lục cố định.
- Bước 4: Thực hiện cuộc gọi thử hoặc thu thử video 15 giây để kiểm tra chất âm và độ sáng đèn.
- Bước 5: Đặt một cốc nước ấm cạnh bàn, hít sâu giữ tâm thế thoải mái và tự tin bấm nút "Bắt đầu phát trực tiếp".

Khám phá trọn bộ thiết bị livestream và sáng tạo nội dung GAERU tại https://gaeru.com/cua-hang và kết nối cùng cộng đồng đối tác tại https://gaeru.com/cau-chuyen.',
